.hg-manager-permission-grid label{display:flex;align-items:center;gap:7px;padding:8px;border:1px solid #e3dbd1;border-radius:8px;background:#fff;cursor:pointer}
.hg-manager-permission-grid input{width:14px!important;height:14px!important;margin:0}
.hg-manager-permission-grid span{font-size:7px!important;font-weight:700!important;text-transform:none!important;letter-spacing:0!important;color:#625b54!important}
.hg-manager-create-permissions{display:grid;gap:7px;padding:12px;border:1px solid #e3dbd1;border-radius:9px;background:#faf8f4}
.hg-manager-create-permissions>strong{font-size:9px}
.hg-manager-create-permissions>small{font-size:7px;color:#8f867b}
.hg-manager-permission-grid.is-owner-disabled{opacity:.42;pointer-events:none}

.hg-manager-log-filters{display:flex;align-items:flex-end;gap:8px;padding:17px 20px;border-bottom:1px solid #eee7de;flex-wrap:wrap}
.hg-manager-log-filters label{display:grid;gap:5px;min-width:180px}
.hg-manager-log-filters label>span{font-size:7px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:#93897e}
.hg-manager-log-filters input,.hg-manager-log-filters select{height:40px;border:1px solid #ddd5ca;border-radius:8px;background:#fbfaf7;padding:0 10px;font:500 9px "Manrope",sans-serif}
.hg-manager-log-filters button,.hg-manager-log-filters a{display:inline-flex;align-items:center;justify-content:center;height:40px;padding:0 13px;border-radius:8px;font-size:8px;font-weight:700;text-decoration:none}
.hg-manager-log-filters button{border:0;background:#2b2622;color:#fff;cursor:pointer}
.hg-manager-log-filters a{border:1px solid #ddd5ca;background:#fff}
.hg-manager-log-list{display:grid}
.hg-manager-log-head,.hg-manager-log-row{display:grid;grid-template-columns:120px 150px 170px minmax(220px,1fr) 110px;gap:12px;align-items:center;padding:11px 20px}
.hg-manager-log-head{background:#faf8f4;border-bottom:1px solid #e8e0d6;color:#8c8378;font-size:7px;font-weight:700;text-transform:uppercase;letter-spacing:.06em}
.hg-manager-log-row{border-bottom:1px solid #f0e9df}
.hg-manager-log-row:last-child{border-bottom:0}
.hg-manager-log-row>span{display:grid;gap:3px;min-width:0}
.hg-manager-log-row strong{font-size:8px}
.hg-manager-log-row small{font-size:7px;line-height:1.45;color:#8f877d;overflow-wrap:anywhere}
.hg-manager-log-row b{justify-self:start;padding:5px 8px;border-radius:999px;background:#f0ede7;color:#6f675e;font-size:7px}

@media(max-width:1100px){.hg-manager-quick-actions{grid-template-columns:repeat(2,1fr)}.hg-manager-product-editor{grid-template-columns:1fr}.hg-manager-product-side{grid-template-columns:1fr 1fr}.hg-manager-customer-row{grid-template-columns:42px 1fr 70px 90px auto}.hg-manager-customer-row>span:nth-child(3),.hg-manager-customer-row>span:nth-child(5){display:none}.hg-manager-staff-list>div{grid-template-columns:1fr 100px auto}.hg-manager-staff-status{grid-column:1/3}.hg-manager-staff-actions{grid-column:3;grid-row:1/3}}
@media(max-width:780px){.hg-manager-head-actions{width:100%}.hg-manager-quick-actions{grid-template-columns:1fr 1fr}.hg-manager-product-fields{grid-template-columns:1fr}.hg-manager-product-fields .is-wide{grid-column:auto}.hg-manager-product-side{grid-template-columns:1fr}.hg-manager-customer-search{align-items:stretch;flex-direction:column}.hg-manager-customer-search label{min-width:0}.hg-manager-customer-row{grid-template-columns:38px 1fr auto}.hg-manager-customer-row>span:nth-child(4),.hg-manager-customer-row>span:nth-child(6){display:none}.hg-manager-staff-list>div{grid-template-columns:1fr auto}.hg-manager-staff-list>div>b,.hg-manager-staff-status{grid-column:1}.hg-manager-staff-actions{grid-column:2;grid-row:1/4;align-self:center;flex-direction:column}}
@media(max-width:900px){.hg-manager-log-list{overflow-x:auto}.hg-manager-log-head,.hg-manager-log-row{min-width:760px}.hg-manager-log-filters label{min-width:150px}}
@media(max-width:520px){.hg-manager-quick-actions{grid-template-columns:1fr}.hg-manager-customer-row{grid-template-columns:38px 1fr}.hg-manager-inline-action{grid-column:2;justify-content:flex-start}.hg-manager-staff-list>div{grid-template-columns:1fr}.hg-manager-staff-actions{grid-column:1;grid-row:auto;flex-direction:row;justify-content:flex-start}.hg-manager-staff-you{justify-self:start}.hg-manager-permission-grid{grid-template-columns:1fr}.hg-manager-log-filters{align-items:stretch;flex-direction:column}.hg-manager-log-filters label{min-width:0}.hg-manager-log-filters button,.hg-manager-log-filters a{width:100%}}
